import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

const app = express();

// Middleware: Parse proxy headers and normalize request path
function proxyAwareMiddleware(req: Request, res: Response, next: NextFunction) {
  // Trust X-Forwarded headers from reverse proxy
  const originalUrl = req.headers['x-original-url'] as string || req.url;
  // Normalize: decode percent-encoding once for routing consistency
  req.url = decodeURIComponent(originalUrl);
  next();
}

// Rate limiter state
const rateLimitMap = new Map<string, { count: number; resetAt: number }>();

function rateLimiter(req: Request, res: Response, next: NextFunction) {
  const clientIp = req.headers['x-forwarded-for'] as string || req.ip;
  const now = Date.now();
  const entry = rateLimitMap.get(clientIp);
  if (entry && entry.resetAt > now) {
    if (entry.count >= 100) {
      return res.status(429).json({ error: 'Rate limited' });
    }
    entry.count++;
  } else {
    rateLimitMap.set(clientIp, { count: 1, resetAt: now + 60000 });
  }
  next();
}

// Auth middleware - checks HMAC signature from internal service
function authMiddleware(req: Request, res: Response, next: NextFunction) {
  const signature = req.headers['x-payment-signature'] as string;
  const timestamp = req.headers['x-payment-timestamp'] as string;
  if (!signature || !timestamp) {
    return res.status(401).json({ error: 'Missing authentication' });
  }
  const age = Math.abs(Date.now() - parseInt(timestamp, 10));
  if (age > 30000) {
    return res.status(401).json({ error: 'Request expired' });
  }
  // Verify HMAC
  const secret = process.env.PAYMENT_HMAC_SECRET || 'default-dev-secret';
  const payload = `${req.method}:${req.url}:${timestamp}`;
  const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(401).json({ error: 'Invalid signature' });
  }
  next();
}

// Access control: admin-only paths
function accessControl(req: Request, res: Response, next: NextFunction) {
  const adminPaths = ['/api/payments/refund', '/api/payments/void', '/api/payments/adjust'];
  const normalizedPath = req.path.toLowerCase();
  const isAdminRoute = adminPaths.some(p => normalizedPath.startsWith(p));
  if (isAdminRoute) {
    const role = req.headers['x-user-role'] as string;
    if (role !== 'admin') {
      return res.status(403).json({ error: 'Admin access required' });
    }
  }
  next();
}

// Amount validation
function validateAmount(amount: string): { valid: boolean; cents: number } {
  const parsed = parseFloat(amount);
  if (isNaN(parsed) || parsed <= 0 || parsed > 999999.99) {
    return { valid: false, cents: 0 };
  }
  // Convert to cents using string manipulation to avoid floating point
  const parts = amount.split('.');
  const dollars = parseInt(parts[0], 10);
  const centsPart = parts[1] ? parts[1].padEnd(2, '0').substring(0, 2) : '00';
  const cents = dollars * 100 + parseInt(centsPart, 10);
  return { valid: true, cents };
}

app.use(express.json());
app.use(proxyAwareMiddleware);
app.use(rateLimiter);
app.use(authMiddleware);
app.use(accessControl);

// Process payment
app.post('/api/payments/charge', (req: Request, res: Response) => {
  const { merchantId, amount, currency, cardToken } = req.body;
  if (!merchantId || !amount || !currency || !cardToken) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  const validation = validateAmount(amount);
  if (!validation.valid) {
    return res.status(400).json({ error: 'Invalid amount' });
  }
  // Process charge (simulated)
  const txId = crypto.randomUUID();
  return res.json({ transactionId: txId, status: 'approved', amountCents: validation.cents });
});

// Admin: Process refund
app.post('/api/payments/refund', (req: Request, res: Response) => {
  const { transactionId, amount, reason } = req.body;
  if (!transactionId || !amount || !reason) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  const validation = validateAmount(amount);
  if (!validation.valid) {
    return res.status(400).json({ error: 'Invalid amount' });
  }
  const refundId = crypto.randomUUID();
  return res.json({ refundId, status: 'processed', amountCents: validation.cents });
});

// Health check - no auth needed but proxy still decodes
app.get('/health', (req: Request, res: Response) => {
  res.json({ status: 'ok' });
});

export default app;
